int minTaps(int n, int *ranges, int rangesSize) {
    (void)rangesSize;
    int *maxReach = (int *)calloc((size_t)n + 1, sizeof(int));
    if (!maxReach) return -1;

    for (int i = 0; i <= n; i++) {
        int left = i - ranges[i];
        if (left < 0) left = 0;
        int right = i + ranges[i];
        if (right > n) right = n;
        if (right > maxReach[left]) maxReach[left] = right;
    }

    int taps = 0, currentEnd = 0, farthest = 0;
